import{_ as s}from"./chunks/3dots_menu.BrLPqWzo.js";import{_ as r,a as o,b as a,c as t,d as i,e as n,f as u,g as l,h as p,i as c,j as d,k as m,l as h,m as f,n as v,o as g,p as b,q as _}from"./chunks/3DM-CU.Cv4Q9_Tx.js";import{_ as q,o as z,c as x,a3 as y}from"./chunks/framework.g9mfNVRQ.js";const T=JSON.parse('{"title":"Menu 3 points","description":"","frontmatter":{"source_hash":"f83c7ecdbb","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/use/3dotsmenu.md","filePath":"fr/use/3dotsmenu.md"}'),k={name:"fr/use/3dotsmenu.md"};function P(S,e,D,V,j,L){return z(),x("div",null,[...e[0]||(e[0]=[y('<img src="'+s+'" style="zoom:75%;"><h3 id="reminders" tabindex="-1">Rappels <a class="header-anchor" href="#reminders" aria-label="Permalink to &quot;Rappels {#reminders}&quot;">​</a></h3><p>Ce menu vous permet de configurer divers rappels : appuyez simplement sur le bouton + en bas à droite.</p><img src="'+r+'" style="zoom:75%;"><p>Donnez-lui le nom de votre choix</p><img src="'+o+'" style="zoom:75%;"><p>L&#39;icône de note de musique <code>1</code> vous permet de choisir le son qui retentira lorsque le rappel se déclenchera.<br> Vous pouvez programmer le rappel pour qu&#39;il se déclenche après un délai défini à partir de maintenant, en choisissant <code>2</code> heures, jours ou semaines et la valeur numérique. Si vous cochez Répéter, il se répétera avec le même délai : par exemple, vous pouvez le régler pour qu&#39;il sonne toutes les 2 semaines.<br> Vous pouvez le régler pour qu&#39;il ne se déclenche qu&#39;en semaine, que le week-end, ou les deux <code>3</code>.<br> Si vous sélectionnez En alternance, il affichera des messages différents <code>4</code> que vous pouvez intervertir avec l&#39;icône à double flèche.<br> Le rappel peut être annoncé à voix haute lorsqu&#39;il se déclenche.<br> Si vous sélectionnez Carillon seulement, le rappel n&#39;aura pas besoin d&#39;être confirmé : il ne sonnera qu&#39;une fois. Sans cette option, il sonnera de façon répétée jusqu&#39;à ce qu&#39;il soit ignoré.<br> À la maison seulement fait que le rappel ne se déclenche que lorsque le téléphone est connecté au Wi-Fi de votre domicile ; voir plus bas comment le configurer.</p><p>Cocher ou décocher les cases affiche des indications sur leur fonction réelle.</p><p>Une fois le rappel configuré, vous pouvez modifier son titre en appuyant dessus.</p><p>Vous pouvez le modifier par un appui long.</p><p>Balayer un rappel vers la gauche le met en veille pour 30 minutes (par défaut) ; vous pouvez changer ce délai avec le bouton en dessous.</p><img src="'+a+'" style="zoom:75%;"><p>Balayer un rappel vers la droite vous permet soit <code>1</code> de le mettre en veille pour la durée sélectionnée en dessous (de 15 minutes à 1 semaine), soit <code>3</code> de le supprimer. Si vous changez d&#39;avis, vous pouvez annuler les modifications <code>2</code>.</p><img src="'+t+'" style="zoom:75%;"><p>Un autre menu à 3 points est disponible en haut à droite.</p><img src="'+i+'" style="zoom:75%;"><p>Vous pouvez définir votre réseau domestique avec Définir le réseau domestique ; il est utilisé lorsque le rappel est réglé sur À la maison seulement.<br> Vous pouvez désactiver les rappels pendant la nuit ; vous pouvez aussi désactiver toutes les alertes, auquel cas la case suivante vous permet de les réactiver (réactiver tous les rappels) le lendemain matin.</p><h3 id="emergency-messages" tabindex="-1">Messages d&#39;urgence <a class="header-anchor" href="#emergency-messages" aria-label="Permalink to &quot;Messages d&#39;urgence {#emergency-messages}&quot;">​</a></h3><p>xDrip peut envoyer automatiquement des SMS dans certaines situations pour alerter d&#39;autres personnes. Cela nécessite évidemment une couverture réseau et une carte SIM active. La localisation du téléphone doit être autorisée pour que xDrip puisse utiliser cette fonction.</p><img src="'+n+'" style="zoom:75%;"><p>Pour la configurer, vous devez d&#39;abord ajouter un contact, éventuellement lui donner un nom, et enfin choisir quelles situations d&#39;urgence déclencheront l&#39;envoi du SMS.</p><img src="'+u+'" style="zoom:75%;"><p>Vous pouvez ensuite envoyer un message de test pour vérifier le bon fonctionnement du système d&#39;urgence.</p><img src="'+l+'" style="zoom:75%;"><h3 id="import-export-features" tabindex="-1">Fonctions d&#39;import/export <a class="header-anchor" href="#import-export-features" aria-label="Permalink to &quot;Fonctions d&#39;import/export {#import-export-features}&quot;">​</a></h3><p>Ce menu propose diverses options pour importer (uniquement la base de données xDrip complète) ou exporter des données.</p><img src="'+p+'" style="zoom:75%;"><p>Voir <a href="./../troubleshoot/reinstall.html#backup">ici</a> pour l&#39;import/export de la base de données et des paramètres.</p><p>Vous pouvez exporter les données depuis une date donnée jusqu&#39;à maintenant, au format SiDiary. Le fichier est enregistré dans <code>/storage/emulated/0/xDrip</code> sous forme de fichier zip contenant la liste des données au format CSV (valeurs séparées par des virgules).</p><img src="'+c+'" style="zoom:75%;"><h3 id="crowd-sources-translation" tabindex="-1">Traduction crowdsourcing <a class="header-anchor" href="#crowd-sources-translation" aria-label="Permalink to &quot;Traduction crowdsourcing {#crowd-sources-translation}&quot;">​</a></h3><p>La traduction de xDrip repose sur des bénévoles, via <a href="https://crowdin.com/project/xdrip" target="_blank" rel="noreferrer">Crowdin</a>.<br> Vous êtes les bienvenus pour y contribuer : contactez les responsables en bas de la page.</p><img src="'+d+'" style="zoom:75%;"><h3 id="events-log" tabindex="-1">Journal d&#39;événements <a class="header-anchor" href="#events-log" aria-label="Permalink to &quot;Journal d&#39;événements {#events-log}&quot;">​</a></h3><p>Le journal d&#39;événements donne de nombreuses indications sur ce que fait xDrip ; vous pouvez ajouter des traces supplémentaires en ajoutant des <a href="./lesscommon.html#extra-logging-settings">tags</a>.</p><img src="'+m+'" style="zoom:75%;"><p>Vous pouvez aussi filtrer les éléments affichés en sélectionnant le journal ou les événements souhaités avec les cases à cocher au-dessus de la liste.<br> Lorsque vous partagez des captures d&#39;écran du journal d&#39;erreurs, veillez à tout activer et à masquer manuellement les informations personnelles (identifiants, numéros de série, ...)</p><p><code>High</code> affiche les erreurs</p><img src="'+h+'" style="zoom:75%;"><p><code>Mid</code> affiche les traces</p><img src="'+f+'" style="zoom:75%;"><p><code>Low</code> affiche tout le reste (importance moindre)</p><p><code>EH</code> affiche les événements de plus grande importance</p><img src="'+v+'" style="zoom:75%;"><p><code>EL</code> affiche les événements de moindre importance.</p><img src="'+g+'" style="zoom:75%;"><h3 id="libre-trend" tabindex="-1">Tendance Libre <a class="header-anchor" href="#libre-trend" aria-label="Permalink to &quot;Tendance Libre {#libre-trend}&quot;">​</a></h3><p>Si vous utilisez un capteur Libre, Afficher la tendance du Freestyle Libre affiche les 45 dernières minutes d&#39;informations du capteur, minute par minute.</p><img src="'+b+'" style="zoom:75%;"><h3 id="share-settings-via-qr-code" tabindex="-1">Partager les paramètres via le code QR <a class="header-anchor" href="#share-settings-via-qr-code" aria-label="Permalink to &quot;Partager les paramètres via le code QR {#share-settings-via-qr-code}&quot;">​</a></h3><p>C&#39;est un raccourci vers Menu / Paramètres / <a href="./copysettings.html">Affichage QR codes</a></p><h3 id="check-for-updated-version" tabindex="-1">Vérifier les mises à jour <a class="header-anchor" href="#check-for-updated-version" aria-label="Permalink to &quot;Vérifier les mises à jour {#check-for-updated-version}&quot;">​</a></h3><p>Cette entrée lance une vérification de version selon les réglages de Menu / Paramètres / <a href="./update.html">xDrip+ Mises à jour</a><br> Si une nouvelle version est disponible, l&#39;écran de téléchargement s&#39;ouvre.</p><img src="'+_+'" style="zoom:75%;"><h3 id="send-feedback-to-developers" tabindex="-1">Envoyer des messages au développeur <a class="header-anchor" href="#send-feedback-to-developers" aria-label="Permalink to &quot;Envoyer des messages au développeur {#send-feedback-to-developers}&quot;">​</a></h3><p>N&#39;utilisez cette fonction que pour envoyer des compliments.</p><p>Pour toute autre demande, préférez les <a href="https://github.com/NightscoutFoundation/xDrip/discussions" target="_blank" rel="noreferrer">discussions GitHub de xDrip</a> ou <a href="https://www.facebook.com/groups/xDripG5" target="_blank" rel="noreferrer">Facebook</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Dernière modification le 15/12/2024</em></a></p>',59)])])}const E=q(k,[["render",P]]);export{T as __pageData,E as default};
